const ALL = { en, fa, ru, zh };
export const LANGS = [['en', 'English'], ['fa', 'فارسی'], ['ru', 'Русский'], ['zh', '中文']];

let current = 'en';
export function setLang(lang) { current = ALL[lang] ? lang : 'en'; }
export function lang() { return current; }
export function isRtl() { return current === 'fa'; }

export function t(key, vars) {
  let s = (ALL[current] && ALL[current][key]) || en[key] || key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}

/** Error code from the native side or the core → readable text. */
export function errText(code) {
  const http = /^HTTP_(\d{3})$/.exec(String(code));
  if (http) return t('e_HTTP', { code: num(Number(http[1])) });
  const k = `e_${code}`;
  return (ALL[current] && ALL[current][k]) || en[k] || t('e_FAILED');
}

/** Numbers in the UI's script (Persian digits for Persian). */
export function num(n, digits = 0) {
  const loc = current === 'fa' ? 'fa-IR' : current === 'ru' ? 'ru-RU' : current === 'zh' ? 'zh-CN' : 'en-US';
  return Number(n).toLocaleString(loc, { maximumFractionDigits: digits, minimumFractionDigits: digits });
}
